import '../../../../styles/reader-v2.css';
import fs from 'node:fs';
import path from 'node:path';

export function getStaticPaths() {
  const paths = [];
  for (let torah = 1; torah <= 50; torah++) {
    paths.push({ params: { part: '1', torah: String(torah) } });
  }
  return paths;
}

const { part, torah } = Astro.params;
const partNum = parseInt(part);
const torahNum = parseInt(torah);

let torahData = null;
let error = null;

try {
  const filePath = path.join(process.cwd(), `public/reader/tanach-bereishit/part-${partNum}/torah-${torahNum}.json`);
  const raw = fs.readFileSync(filePath, 'utf8');
  torahData = JSON.parse(raw);
} catch (e) {
  error = `Chapter ${torahNum} not found`;
}

if (!torahData && !error) error = 'Content not available';

const bookName = 'Tanach - Genesis';
const bookHebrew = 'תנ"ך - בראשית';

const pageTitle = torahData
  ? `${torahData.hebrewTitle || torahData.title} - Tanach`
  : 'Chapter Not Found';
const pageDesc = torahData
  ? (() => {
    const snippet = (torahData.segments?.find(s => s.en)?.en || '').replace(/<[^>]+>/g, '').slice(0, 120);
    return `Read ${torahData.title} from Tanach - Genesis online free. ${snippet ? snippet + '...' : 'Hebrew text with English translation on ajew.org.'}`;
  })()
  : '';

const structuredData = torahData ? JSON.stringify({
  "@context": "https://schema.org",
  "@type": "Article",
  "headline": `${torahData.title} - Tanach`,
  "alternativeHeadline": torahData.hebrewTitle || '',
  "author": { "@type": "Organization", "name": "Tanach" },
  "publisher": { "@type": "Organization", "name": "ajew.org" },
  "inLanguage": ["he"],
  "isPartOf": { "@type": "Book", "name": "Tanach - Genesis" },
  "url": `https://ajew.org/reader/tanach-bereishit/${partNum}/${torahNum}`
}) : '';

// Genesis 6:8 closes Beraishis; the source supplement is also studied on Noach.
const noachEntry = torahData && torahNum === 6 ? {
  book: "parsha-packets", section: "noach", label: "Noach — Rabbainu",
  sectionTitle: "Finding favor · Genesis 6:8",
  url: "/reader/parsha-packets/noach.json",
  readerUrl: "/parsha/noach/#noach-source-supplement",
} : null;

// LN verse-by-verse commentary
const lnBookSlug = 'tanach-bereishit';
// Hilchasa Kinachamani citation tab (facts: verse -> Breslov sources)
const hkData = (hkIndex as any)?.tanach?.['tanach-bereishit'];
const hkEntry = torahData && hkData && Array.isArray(hkData.chapters) && hkData.chapters.includes(torahNum) ? {
  book: 'hilchasa-kinachamani',
  section: `tanach-bereishit-${torahNum}`,
  label: 'הלכתא כנחמני',
  sectionTitle: 'ציטוטים בברסלב',
  url: `/hk-citations/tanach-bereishit-${torahNum}.json`,
  readerUrl: hkData.bookPage || '/reader/hilchasa-kinachamani/1/1',
  openLabel: 'למפתח הספר ↗'
} : null;

// Breslov on the Parsha — all Breslov teachings on each Torah verse
const bpChapters = [1, 2, 8]; // reviewed selections only, not whole chapters
const breslovEntry = torahData && bpChapters.includes(torahNum) ? {
  book: "breslov-parsha",
  section: "bereishit-" + torahNum,
  label: "ברסלב על הפרשה",
  sectionTitle: "Breslov on the Parsha",
  url: "/reader/breslov-parsha/bereishit-" + torahNum + ".json"
} : null;

// A distinct source-qualified edition, selected only by the actual exported index.
const qualified = torahData && partNum === 1 ? qualifiedChapter(torahNum) : {matches: [], selection: null};
const qualifiedBreslovEntry = qualified.matches.length ? {
  book: `breslov-parsha-${qualified.matches[0].namespace}`,
  section: `bereishit-${torahNum}`,
  label: 'ברסלב — ליקוטים מסויגים',
  sectionTitle: 'Qualified supplied source selections',
  url: qualified.matches[0].index.chapters[String(torahNum)].url,
} : null;
const qualifiedChapterData = qualified.selection;

const commentaryEntry = torahData ? {
  related_commentaries: [
    ...(hkEntry ? [hkEntry] : []),
    ...(noachEntry ? [noachEntry] : []),
    ...(breslovEntry && !qualifiedBreslovEntry ? [breslovEntry] : []),
    ...(qualifiedBreslovEntry ? [qualifiedBreslovEntry] : []),
    {
      book: "likutay-nanach",
      section: lnBookSlug,
      label: "Likutay Nanach",
      sectionTitle: "Verse-by-Verse",
      url: "/reader/likutay-nanach/tanach/tanach-bereishit-${torahNum}.json"
    }
  ]
} : null;
const qualifiedTabIndex = commentaryEntry?.related_commentaries.findIndex(c => c === qualifiedBreslovEntry);
const qualifiedTabId = qualifiedBreslovEntry ? `c-${qualifiedTabIndex}-${qualifiedBreslovEntry.book}` : null;
const breadcrumbData = torahData ? JSON.stringify({
  "@context": "https://schema.org",
  "@type": "BreadcrumbList",
  "itemListElement": [
    { "@type": "ListItem", "position": 1, "name": "Library", "item": "https://ajew.org/reader" },
    { "@type": "ListItem", "position": 2, "name": "Tanach - Genesis", "item": `https://ajew.org/reader/tanach-bereishit/${partNum}/` },
    { "@type": "ListItem", "position": 3, "name": torahData.hebrewTitle || torahData.title }
  ]
}) : '';
// URL adaptation only; source JSON, bodies and publication holds stay unchanged.
const readerNavigation = normalizeReaderNavigation(torahData?.navigation, {
  book: 'tanach-bereishit', part: partNum, torah: torahNum, minTorah: 1, maxTorah: 50,
  contentDir: path.join(process.cwd(), `public/reader/tanach-bereishit/part-${partNum}`),
});

