  "@type": "Article",
  "headline": `${torahData.title} - Tanach`,
  "alternativeHeadline": torahData.hebrewTitle || '',
  "author": { "@type": "Organization", "name": "Tanach" },
  "publisher": { "@type": "Organization", "name": "ajew.org" },
  "inLanguage": ["he"],
  "isPartOf": { "@type": "Book", "name": "Tanach - Genesis" },
  "url": `https://ajew.org/reader/tanach-bereishit/${partNum}/${torahNum}`
}) : '';

// Genesis 6:8 closes Beraishis; the source supplement is also studied on Noach.
const noachEntry = torahData && torahNum === 6 ? {
  book: "parsha-packets", section: "noach", label: "Noach — Rabbainu",
  sectionTitle: "Finding favor · Genesis 6:8",
  url: "/reader/parsha-packets/noach.json",
  readerUrl: "/parsha/noach/#noach-source-supplement",
} : null;

// LN verse-by-verse commentary
const lnBookSlug = 'tanach-bereishit';
// Hilchasa Kinachamani citation tab (facts: verse -> Breslov sources)
const hkData = (hkIndex as any)?.tanach?.['tanach-bereishit'];
const hkEntry = torahData && hkData && Array.isArray(hkData.chapters) && hkData.chapters.includes(torahNum) ? {
  book: 'hilchasa-kinachamani',
  section: `tanach-bereishit-${torahNum}`,
  label: 'הלכתא כנחמני',
  sectionTitle: 'ציטוטים בברסלב',
  url: `/hk-citations/tanach-bereishit-${torahNum}.json`,
  readerUrl: hkData.bookPage || '/reader/hilchasa-kinachamani/1/1',
  openLabel: 'למפתח הספר ↗'
} : null;

// Breslov on the Parsha — all Breslov teachings on each Torah verse
const bpChapters = [1, 2, 8]; // reviewed selections only, not whole chapters
const breslovEntry = torahData && bpChapters.includes(torahNum) ? {
  book: "breslov-parsha",
  section: "bereishit-" + torahNum,
  label: "ברסלב על הפרשה",
  sectionTitle: "Breslov on the Parsha",
  url: "/reader/breslov-parsha/bereishit-" + torahNum + ".json"
} : null;

// A distinct source-qualified edition, selected only by the actual exported index.
const qualified = torahData && partNum === 1 ? qualifiedChapter(torahNum) : {matches: [], selection: null};
const qualifiedBreslovEntry = qualified.matches.length ? {
  book: `breslov-parsha-${qualified.matches[0].namespace}`,
  section: `bereishit-${torahNum}`,
  label: 'ברסלב — ליקוטים מסויגים',
  sectionTitle: 'Qualified supplied source selections',
  url: qualified.matches[0].index.chapters[String(torahNum)].url,
