      <script src="/reader-source-exact.js?v=1" defer></script>
      <script src="/reader-editions.js?v=a8092a5937318cf005791ac6ee7547ce6eb96d9d7547e17d40584fcabdf4cf73" defer></script>
      <script src="/reader-script.js?v=parsha-author-20261018-r1" defer></script>
      <script src="/reader-v2.js?v=reader-editions-20261002" defer></script>
      <script src="/pwa-register.js" defer></script>
      <script src="/tts-fix.js" defer></script>
    </div>
  )}
</Layout>

