      sectionTitle: "Verse-by-Verse",
      url: "/reader/likutay-nanach/tanach/tanach-daniel-${torahNum}.json"
    }
  ]
} : null;
const breadcrumbData = torahData ? JSON.stringify({
  "@context": "https://schema.org",
  "@type": "BreadcrumbList",
  "itemListElement": [
    { "@type": "ListItem", "position": 1, "name": "Library", "item": "https://ajew.org/reader" },
    { "@type": "ListItem", "position": 2, "name": "Tanach - Daniel", "item": `https://ajew.org/reader/tanach-daniel/${partNum}/` },
    { "@type": "ListItem", "position": 3, "name": torahData.hebrewTitle || torahData.title }
  ]
}) : '';
// URL adaptation only; source JSON, bodies and publication holds stay unchanged.
const readerNavigation = normalizeReaderNavigation(torahData?.navigation, {
  book: 'tanach-daniel', part: partNum, torah: torahNum, minTorah: 1, maxTorah: 12,
  contentDir: path.join(process.cwd(), `public/reader/tanach-daniel/part-${partNum}`),
});

