        <a href={`/reader/tanach-devarim/${partNum}`}>Book Index</a>
        <a href="/reader">All Books</a>
        {readerNavigation.nextUrl ? (
          <a href={readerNavigation.nextUrl} data-dir="next">Next &rarr;</a>
