  "itemListElement": [
    { "@type": "ListItem", "position": 1, "name": "Library", "item": "https://ajew.org/reader" },
    { "@type": "ListItem", "position": 2, "name": "Tanach - Habakkuk", "item": `https://ajew.org/reader/tanach-havakkuk/${partNum}/` },
    { "@type": "ListItem", "position": 3, "name": torahData.hebrewTitle || torahData.title }
  ]
}) : '';
// URL adaptation only; source JSON, bodies and publication holds stay unchanged.
const readerNavigation = normalizeReaderNavigation(torahData?.navigation, {
  book: 'tanach-havakkuk', part: partNum, torah: torahNum, minTorah: 1, maxTorah: 3,
  contentDir: path.join(process.cwd(), `public/reader/tanach-havakkuk/part-${partNum}`),
});

