    return `Read ${torahData.title} from Tanach - Hosea online free. ${snippet ? snippet + '...' : 'Hebrew text with English translation on ajew.org.'}`;
  })()
  : '';

const structuredData = torahData ? JSON.stringify({
  "@context": "https://schema.org",
  "@type": "Article",
