    { "@type": "ListItem", "position": 2, "name": "Tanach - Hosea", "item": `https://ajew.org/reader/tanach-hoshea/${partNum}/` },
    { "@type": "ListItem", "position": 3, "name": torahData.hebrewTitle || torahData.title }
