}

const { part, torah } = Astro.params;
const partNum = parseInt(part);
const torahNum = parseInt(torah);

let torahData = null;
let error = null;

try {
  const filePath = path.join(process.cwd(), `public/reader/tanach-mishlei/part-${partNum}/torah-${torahNum}.json`);
