import '../../../../styles/reader.css';
import '../../../../styles/reader-v2.css';
import fs from 'node:fs';
import path from 'node:path';

export function getStaticPaths() {
  const paths = [];
  for (let torah = 1; torah <= 1; torah++) {
    paths.push({ params: { part: '1', torah: String(torah) } });
  }
  return paths;
}

const { part, torah } = Astro.params;
const partNum = parseInt(part);
const torahNum = parseInt(torah);

let torahData = null;
let error = null;

try {
  const filePath = path.join(process.cwd(), `public/reader/tanach-ovadya/part-${partNum}/torah-${torahNum}.json`);
  const raw = fs.readFileSync(filePath, 'utf8');
  torahData = JSON.parse(raw);
} catch (e) {
  error = `Chapter ${torahNum} not found`;
}

if (!torahData && !error) error = 'Content not available';

const bookName = 'Tanach - Obadiah';
const bookHebrew = 'תנ"ך - עובדיה';

const pageTitle = torahData
  ? `${torahData.hebrewTitle || torahData.title} - Tanach`
  : 'Chapter Not Found';
const pageDesc = torahData
  ? (() => {
    const snippet = (torahData.segments?.find(s => s.en)?.en || '').replace(/<[^>]+>/g, '').slice(0, 120);
    return `Read ${torahData.title} from Tanach - Obadiah online free. ${snippet ? snippet + '...' : 'Hebrew text with English translation on ajew.org.'}`;
  })()
  : '';

const structuredData = torahData ? JSON.stringify({
  "@context": "https://schema.org",
  "@type": "Article",
  "headline": `${torahData.title} - Tanach`,
  "alternativeHeadline": torahData.hebrewTitle || '',
  "author": { "@type": "Organization", "name": "Tanach" },
  "publisher": { "@type": "Organization", "name": "ajew.org" },
  "inLanguage": ["he"],
  "isPartOf": { "@type": "Book", "name": "Tanach - Obadiah" },
  "url": `https://ajew.org/reader/tanach-ovadya/${partNum}/${torahNum}`
}) : '';

// LN verse-by-verse commentary
const lnBookSlug = 'tanach-ovadya';
// Hilchasa Kinachamani citation tab (facts: verse -> Breslov sources)
const hkData = (hkIndex as any)?.tanach?.['tanach-ovadya'];
const hkEntry = torahData && hkData && Array.isArray(hkData.chapters) && hkData.chapters.includes(torahNum) ? {
  book: 'hilchasa-kinachamani',
  section: `tanach-ovadya-${torahNum}`,
  label: 'הלכתא כנחמני',
  sectionTitle: 'ציטוטים בברסלב',
  url: `/hk-citations/tanach-ovadya-${torahNum}.json`,
  readerUrl: hkData.bookPage || '/reader/hilchasa-kinachamani/1/1',
  openLabel: 'למפתח הספר ↗'
} : null;

const commentaryEntry = torahData ? {
  related_commentaries: [
    ...(hkEntry ? [hkEntry] : []),
    {
      book: "likutay-nanach",
      section: lnBookSlug,
      label: "Likutay Nanach",
      sectionTitle: "Verse-by-Verse",
      url: "/reader/likutay-nanach/tanach/tanach-ovadya-${torahNum}.json"
    }
  ]
} : null;
const breadcrumbData = torahData ? JSON.stringify({
  "@context": "https://schema.org",
  "@type": "BreadcrumbList",
  "itemListElement": [
    { "@type": "ListItem", "position": 1, "name": "Library", "item": "https://ajew.org/reader" },
    { "@type": "ListItem", "position": 2, "name": "Tanach - Obadiah", "item": `https://ajew.org/reader/tanach-ovadya/${partNum}/` },
    { "@type": "ListItem", "position": 3, "name": torahData.hebrewTitle || torahData.title }
  ]
}) : '';
// URL adaptation only; source JSON, bodies and publication holds stay unchanged.
const readerNavigation = normalizeReaderNavigation(torahData?.navigation, {
  book: 'tanach-ovadya', part: partNum, torah: torahNum, minTorah: 1, maxTorah: 1,
  contentDir: path.join(process.cwd(), `public/reader/tanach-ovadya/part-${partNum}`),
});

