}) : '';

// LN verse-by-verse commentary
const lnBookSlug = 'tanach-tzefanya';
// Hilchasa Kinachamani citation tab (facts: verse -> Breslov sources)
const hkData = (hkIndex as any)?.tanach?.['tanach-tzefanya'];
const hkEntry = torahData && hkData && Array.isArray(hkData.chapters) && hkData.chapters.includes(torahNum) ? {
  book: 'hilchasa-kinachamani',
  section: `tanach-tzefanya-${torahNum}`,
  label: 'הלכתא כנחמני',
  sectionTitle: 'ציטוטים בברסלב',
  url: `/hk-citations/tanach-tzefanya-${torahNum}.json`,
  readerUrl: hkData.bookPage || '/reader/hilchasa-kinachamani/1/1',
  openLabel: 'למפתח הספר ↗'
} : null;

const commentaryEntry = torahData ? {
  related_commentaries: [
    ...(hkEntry ? [hkEntry] : []),
    {
      book: "likutay-nanach",
      section: lnBookSlug,
      label: "Likutay Nanach",
      sectionTitle: "Verse-by-Verse",
      url: "/reader/likutay-nanach/tanach/tanach-tzefanya-${torahNum}.json"
    }
