  "@context": "https://schema.org",
  "@type": "BreadcrumbList",
  "itemListElement": [
    { "@type": "ListItem", "position": 1, "name": "Library", "item": "https://ajew.org/reader" },
    { "@type": "ListItem", "position": 2, "name": "Tanach - Zephaniah", "item": `https://ajew.org/reader/tanach-tzefanya/${partNum}/` },
    { "@type": "ListItem", "position": 3, "name": torahData.hebrewTitle || torahData.title }
  ]
}) : '';
// URL adaptation only; source JSON, bodies and publication holds stay unchanged.
const readerNavigation = normalizeReaderNavigation(torahData?.navigation, {
  book: 'tanach-tzefanya', part: partNum, torah: torahNum, minTorah: 1, maxTorah: 3,
  contentDir: path.join(process.cwd(), `public/reader/tanach-tzefanya/part-${partNum}`),
});

