  "url": `https://ajew.org/reader/tanach-vayikra/${partNum}/${torahNum}`
}) : '';

// LN verse-by-verse commentary
const lnBookSlug = 'tanach-vayikra';
// Hilchasa Kinachamani citation tab (facts: verse -> Breslov sources)
const hkData = (hkIndex as any)?.tanach?.['tanach-vayikra'];
const hkEntry = torahData && hkData && Array.isArray(hkData.chapters) && hkData.chapters.includes(torahNum) ? {
  book: 'hilchasa-kinachamani',
  section: `tanach-vayikra-${torahNum}`,
  label: 'הלכתא כנחמני',
  sectionTitle: 'ציטוטים בברסלב',
  url: `/hk-citations/tanach-vayikra-${torahNum}.json`,
  readerUrl: hkData.bookPage || '/reader/hilchasa-kinachamani/1/1',
  openLabel: 'למפתח הספר ↗'
} : null;

const commentaryEntry = torahData ? {
  related_commentaries: [
    ...(hkEntry ? [hkEntry] : []),
    {
      book: "likutay-nanach",
      section: lnBookSlug,
      label: "Likutay Nanach",
      sectionTitle: "Verse-by-Verse",
      url: "/reader/likutay-nanach/tanach/tanach-vayikra-${torahNum}.json"
    }
  ]
} : null;
const breadcrumbData = torahData ? JSON.stringify({
  "@context": "https://schema.org",
  "@type": "BreadcrumbList",
  "itemListElement": [
    { "@type": "ListItem", "position": 1, "name": "Library", "item": "https://ajew.org/reader" },
    { "@type": "ListItem", "position": 2, "name": "Tanach - Leviticus", "item": `https://ajew.org/reader/tanach-vayikra/${partNum}/` },
    { "@type": "ListItem", "position": 3, "name": torahData.hebrewTitle || torahData.title }
  ]
}) : '';
// URL adaptation only; source JSON, bodies and publication holds stay unchanged.
const readerNavigation = normalizeReaderNavigation(torahData?.navigation, {
  book: 'tanach-vayikra', part: partNum, torah: torahNum, minTorah: 1, maxTorah: 27,
  contentDir: path.join(process.cwd(), `public/reader/tanach-vayikra/part-${partNum}`),
});

