  sectionTitle: 'ציטוטים בברסלב',
  url: `/hk-citations/tanach-yehoshua-${torahNum}.json`,
  readerUrl: hkData.bookPage || '/reader/hilchasa-kinachamani/1/1',
  openLabel: 'למפתח הספר ↗'
} : null;

const commentaryEntry = torahData ? {
  related_commentaries: [
    ...(hkEntry ? [hkEntry] : []),
    {
      book: "likutay-nanach",
      section: lnBookSlug,
      label: "Likutay Nanach",
      sectionTitle: "Verse-by-Verse",
      url: `/reader/likutay-nanach/tanach/tanach-${lnBookSlug}-${torahNum}.json`
    }
  ]
} : null;
const pageTitle = torahData
  ? `${torahData.hebrewTitle || torahData.title} - Tanach`
  : 'Chapter Not Found';
const pageDesc = torahData
  ? (() => {
    const snippet = (torahData.segments?.find(s => s.en)?.en || '').replace(/<[^>]+>/g, '').slice(0, 120);
